"""Build commerce-gap-report/index.html from src/report.html.

src/report.html is the editable source. It is also what gets published to the
claude.ai artifact, which adds its own <html>/<head>/<body> wrapper, so the
source has none. This script adds that wrapper for GitHub Pages.

Run from anywhere:  python3 commerce-gap-report/src/build.py
"""
from pathlib import Path

here = Path(__file__).resolve().parent
src = (here / "report.html").read_text(encoding="utf-8")
out = (
    "<!doctype html>\n"
    "<!-- GENERATED by src/build.py from src/report.html. Edit the source, not this file. -->\n"
    '<html lang="en">\n<head>\n'
    + src.split("<style>", 1)[0]
    + "<style>"
    + src.split("<style>", 1)[1].split("</style>", 1)[0]
    + "</style>\n</head>\n<body>\n"
    + src.split("</style>", 1)[1].lstrip("\n")
    + "\n</body>\n</html>\n"
)
(here.parent / "index.html").write_text(out, encoding="utf-8")
print("wrote", here.parent / "index.html")
